// Extends the KPK oracle with two same-colour pawns and promotion sacrifices.
(()=>{'use strict';const single=window.PawnEndgameOracle,idx=s=>'abcdefgh'.indexOf(s[0])+(Number(s[1])-1)*8,pairs=Array.from({length:64},()=>[]);let n=0;for(let p=8;p<56;p++)for(let q=p+1;q<56;q++)pairs[p][q]=n++;
function evaluate(game){const pieces=game.board().flat().filter(Boolean),pawns=pieces.filter(p=>p.type==='p'),promoted=pieces.find(p=>!['k','p'].includes(p.type));if(promoted){if(game.isStalemate()||game.isInsufficientMaterial())return {win:false,distance:0};const capture=game.turn()!==promoted.color&&game.moves({verbose:true}).find(m=>m.captured&&m.to===promoted.square);if(capture){const probe=new window.Chess(game.fen());probe.move(capture);const result=evaluate(probe);return {...result,distance:0}}return {win:true,distance:0}}if(pawns.length<2)return single.evaluate(game);if(pawns.length!==2||pawns[0].color!==pawns[1].color)throw Error('Unsupported endgame material');const color=pawns[0].color,flip=color==='b'?56:0;let [p,q]=pawns.map(x=>idx(x.square)^flip).sort((a,b)=>a-b);const a=idx(pieces.find(x=>x.type==='k'&&x.color===color).square)^flip,d=idx(pieces.find(x=>x.type==='k'&&x.color!==color).square)^flip,t=game.turn()===color?1:0,key=((pairs[p][q]*64+a)*64+d)*2+t,value=window.TWO_PAWN_TABLE[key];if(value===255||value===undefined)throw Error('Invalid KPPK state: '+game.fen());return {win:value>0,distance:value,pawnColor:color,pawnCount:2}}
window.PawnEndgameOracle={evaluate};window.RookPawnOracle=window.PawnEndgameOracle;
})();
